-- GENERATED by Build-Sql.py. Read-only: existing publishers on any of the Build #125 domains (any country, www-insensitive) or similar names.
SELECT p.id, p.name, c.iso_code, p.domain, p.feed_status FROM publishers p JOIN countries c ON c.id = p.country_id
 WHERE regexp_replace(lower(p.domain), '^www\.', '') IN ('atolltimes.mv','corporatemaldives.com','mehielinfo.net','artici.info')
    OR p.name ILIKE ANY (ARRAY['%atoll%','%corporate maldives%','%mehiel%','%artici%']);
